  "schema_version": "scientist-design-v1",
  "scenario": "A person is interviewing for a job as a lawyer",
  "agents": [
    {
      "name": "Interviewer",
      "role": "Hiring manager",
      "goal": "Assess the candidate's suitability for the legal position",
      "constraints": ["Evaluate based on experience and communication skills"]
    },
    {
      "name": "Candidate",
      "role": "Job applicant",
      "goal": "Demonstrate competence and secure the job",
      "constraints": ["Answer questions without prior knowledge of the interviewer's expectations"]
    },
    {
      "name": "Recruiter",
      "role": "HR representative",
      "goal": "Ensure the candidate meets company standards",
      "constraints": ["Cannot share confidential company details"]
    }
  ],
  "outcome": {
    "name": "Job offer",
    "operationalization": "Whether the candidate receives a formal offer after the interview",
    "measurement_question": "Did the candidate receive a job offer?",
    "respondent": "Candidate"
  },
  "causes": [
    {
      "name": "Communication clarity",
      "hypothesis": "Clear and structured responses improve the candidate's perceived competence",
      "predicted_direction": "increase",
      "treatment_values": ["Structured with examples", "Brief and direct", "Unclear and disorganized"]
    },
    {
      "name": "Legal experience",
      "hypothesis": "More relevant experience increases the likelihood of a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["10+ years in corporate law", "5 years in criminal law", "No prior legal experience"]
    },
    {
      "name": "Confidence level",
      "hypothesis": "Higher confidence during the interview correlates with better job outcomes",
      "predicted_direction": "increase",
      "treatment_values": ["Confident and assertive", "Nervous but articulate", "Passive and hesitant"]
    }
  ],
  "information_scope": {
    "public": ["Job description", "Company background", "Interview format"],
    "private": [
      {
        "agent": "Interviewer",
        "information": ["Previous interview notes", "Internal hiring criteria", "Company financials"]
      },
      {
        "agent": "Candidate",
        "information": ["Personal strengths", "Past interview performance", "Salary expectations"]
      },
      {
        "agent": "Recruiter",
        "information": ["HR policies", "Candidate background checks", "Internal hiring timeline"]
      }
    ]
  },
  "interaction": {
    "order": ["Interviewer", "Candidate", "Recruiter"],
    "max_turns": 3,
    "stopping_rule": "The interaction stops after the recruiter provides feedback to the candidate."
  }
}

