{
  "schema_version": "scientist-design-v1",
  "scenario": "3 bidders participating in an auction for a piece of art starting at fifty dollars",
  "agents": [
    {
      "name": "Agent A",
      "role": "Conservative bidder",
      "goal": "Maximize profit while minimizing risk",
      "constraints": ["Bids only when confident in value", "No overbidding by more than 20%"]
    },
    {
      "name": "Agent B",
      "role": "Speculative bidder",
      "goal": "Achieve maximum possible profit",
      "constraints": ["Bids aggressively to outbid others", "No limit on bid amount"]
    },
    {
      "name": "Agent C",
      "role": "Strategic bidder",
      "goal": "Secure the item at the lowest possible price",
      "constraints": ["Bids based on others' actions", "No bidding above $100"]
    }
  ],
  "outcome": {
    "name": "Final auction price",
    "operationalization": "The final price the art piece is sold for in the auction",
    "measurement_question": "What is the final selling price of the art piece?",
    "respondent": "Auction house"
  },
  "causes": [
    {
      "name": "Bidder A's confidence",
      "hypothesis": "Higher confidence leads to higher bids",
      "predicted_direction": "increase",
      "treatment_values": ["High", "Medium", "Low"]
    },
    {
      "name": "Bidder B's aggressiveness",
      "hypothesis": "More aggressive bidding increases final price",
      "predicted_direction": "increase",
      "treatment_values": ["Aggressive", "Moderate", "Passive"]
    },
    {
      "name": "Bidder C's budget limit",
      "hypothesis": "Lower budget limits reduce final price",
      "predicted_direction": "decrease",
      "treatment_values": ["$100", "$150", "$200"]
    }
  ],
  "information_scope": {
    "public": ["Starting price of $50", "Number of bidders", "Current highest bid"],
    "private": [
      {
        "agent": "Agent A",
        "information": ["Estimated value of the art", "Risk tolerance level"]
      },
      {
        "agent": "Agent B",
        "information": ["Market demand analysis", "Personal budget"]
      },
      {
        "agent": "Agent C",
        "information": ["Bidder behavior patterns", "Personal valuation"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent A", "Agent B", "Agent C"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when a bidder places a bid above the current highest bid and no further bids are placed"
  }
}

